import {
  Activity, ArrowDownToLine, ArrowLeft, ArrowRight, ArrowUpRight, BarChart3, Bell, Box, Boxes, Check, CheckCircle2,
  ChevronDown, ChevronLeft, ChevronRight, CircleDollarSign, ClipboardList, Clock3, CreditCard, Download, Eye, Filter,
  Grid2X2, Headphones, House, LayoutDashboard, LogIn, LogOut, Menu, Minus, Package, Plus, Search, Settings, ShieldCheck,
  ShoppingBag, ShoppingCart, SlidersHorizontal, Sparkles, Tag, Trash2, Truck, Upload, UserCircle, Users, Wallet, X,
} from 'lucide-react';
import { activities, categories, formatQ, orders, products, users } from './data/mockData';
import { useApp } from './contexts/AppContext';
import { fetchCatalogFromApi } from './services/productService';
